(n, m) = map(int, input().split())
cnt = [0] * 10
ans = [0] * n
s = map(int, input().strip())
for (index, i) in enumerate(s):
	b1 = 0
	b2 = 0
	for j in range(10):
		if j > i:
			b2 += cnt[j] * (i - j)
		elif i > j:
			b1 += cnt[j] * (i - j)
	cnt[i] += 1
	ans[index] += b1 - b2
for _ in range(m):
	print(ans[int(input()) - 1])
